      ACCEPT_TOKEN(aux_sym_character_token1);
      END_STATE();
    case 780:
      ACCEPT_TOKEN(aux_sym_character_token1);
      if (lookahead == '/') ADVANCE(272);
      END_STATE();
    case 781:
      ACCEPT_TOKEN(aux_sym_character_token1);
      if (lookahead == '/') ADVANCE(780);
